-- Migration: aggiunge configurazioni listino per PETG, PE_PCR, BIOBASED
-- su tutte le capacità (inclusa 400 ml) e colori NBN/COL
-- Costi MP: PETG=3.822, PE_PCR=1.98, BIOBASED=3.72 (già in anagrafiche materiali)
-- 400 ml eredita peso (38 g) e velocità (350 pz/h) dal 300/350 ml


ON CONFLICT (capacity_id, material_id, color_id) DO UPDATE SET
    peso_disegno_g = EXCLUDED.peso_disegno_g,
    rinfusa_ricarico_div_100 = EXCLUDED.rinfusa_ricarico_div_100,
    mp_costos_kg = EXCLUDED.mp_costos_kg,
    mp_utilizzi_pct = EXCLUDED.mp_utilizzi_pct,
    master_color_costo_kg = EXCLUDED.master_color_costo_kg,
    imballo_items = EXCLUDED.imballo_items,
    pezzi_pallet = EXCLUDED.pezzi_pallet,
    ore_uomo = EXCLUDED.ore_uomo,
    costo_rsu = EXCLUDED.costo_rsu,
    velocita_pz_h = EXCLUDED.velocita_pz_h,
    rsu_unit = EXCLUDED.rsu_unit,
    rsu_unit_rinfusa = EXCLUDED.rsu_unit_rinfusa,
    costo_orario_macchina = EXCLUDED.costo_orario_macchina,
    costo_orario_rsu = EXCLUDED.costo_orario_rsu,
    ricarico_costi_ind = EXCLUDED.ricarico_costi_ind,
    updated_at = now();
